public interface IEmailClient
{
    Task SendEmailAsync(string to, string subject, string body, CancellationToken cancellationToken = default);

    /// <summary>Payload form backing the DSL's <c>Email.send({ to: ..., subject: ...,
    /// body: ... })</c>. The DSL object literal transpiles to a JsonObject, and the
    /// keyed contract (<c>to</c> required; <c>subject</c>/<c>body</c> optional,
    /// defaulting to empty; any further key carried as a vendor option) is the same
    /// one every other language target realizes.</summary>
    Task SendAsync(System.Text.Json.Nodes.JsonObject payload, CancellationToken cancellationToken = default);

    /// <summary>Payload form backing the DSL's <c>Email.sendTemplate({ to: ...,
    /// template: ..., data: ... })</c>.</summary>
